package com.finstack.budget;
import com.finstack.budget.dto.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/budgets") public class BudgetController {private final BudgetService service;public BudgetController(BudgetService s){service=s;}@PostMapping public ResponseEntity<BudgetResponse> create(@Valid @RequestBody BudgetCreateRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));}@GetMapping public List<BudgetResponse> list(@RequestParam(required=false)Boolean active){return service.list(active);}@GetMapping("/{id}") public BudgetResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping("/{id}/progress") public BudgetProgressResponse progress(@PathVariable UUID id){return service.progress(id);}@PutMapping("/{id}") public BudgetResponse update(@PathVariable UUID id,@Valid @RequestBody BudgetUpdateRequest r){return service.update(id,r);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable UUID id){service.deactivate(id);return ResponseEntity.noContent().build();}}
